mapper.select:
SELECT p.id, p.category_id, p.name, p.subtitle, p.price, p.stock, p.cover_image, p.mockup_image, p.description, p.is_customizable, p.is_recommend, p.sales_count, p.sort, p.status, p.created_at, p.updated_at, pc.name AS category_name FROM product p LEFT JOIN product_category pc ON p.category_id = pc.id AND pc.deleted = 0 WHERE p.deleted = 0
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.id = #{keyword})
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND p.is_recommend = #{isRecommend}
ORDER BY p.sort ASC, p.created_at DESC
